CREATE TABLE oauth_server_settings(singleton integer PRIMARY KEY CHECK(singleton=1),issuer text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 1);
INSERT INTO oauth_server_settings(singleton) VALUES(1);
CREATE TABLE oauth_signing_keys(id text PRIMARY KEY,private_sealed bytea NOT NULL,public_jwk jsonb NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),retire_at timestamptz);
CREATE UNIQUE INDEX oauth_one_active_key ON oauth_signing_keys(active) WHERE active;
CREATE TABLE oauth_clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,secret_hash text NOT NULL,redirect_uris text[] NOT NULL,scopes text[] NOT NULL,allowed_users uuid[] NOT NULL DEFAULT '{}',allowed_departments uuid[] NOT NULL DEFAULT '{}',allow_all_users boolean NOT NULL DEFAULT false,client_credentials boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT false,claim_mapping jsonb NOT NULL DEFAULT '{}',version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES oauth_clients(id),user_id uuid NOT NULL REFERENCES users(id),scopes text[] NOT NULL,version bigint NOT NULL DEFAULT 1,revoked_at timestamptz,UNIQUE(client_id,user_id));
CREATE TABLE oauth_pending_authorizations(token_hash text PRIMARY KEY,session_hash text NOT NULL,user_id uuid NOT NULL REFERENCES users(id),client_id uuid NOT NULL REFERENCES oauth_clients(id),client_version bigint NOT NULL,server_version bigint NOT NULL,auth_epoch bigint NOT NULL,request jsonb NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE oauth_codes(token_hash text PRIMARY KEY,client_id uuid NOT NULL REFERENCES oauth_clients(id),client_version bigint NOT NULL,server_version bigint NOT NULL,auth_epoch bigint NOT NULL,user_id uuid NOT NULL REFERENCES users(id),user_version bigint NOT NULL,consent_id uuid NOT NULL,consent_version bigint NOT NULL,redirect_uri text NOT NULL,challenge text NOT NULL,nonce text NOT NULL,scopes text[] NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE oauth_token_families(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES oauth_clients(id),client_version bigint NOT NULL,server_version bigint NOT NULL,auth_epoch bigint NOT NULL,user_id uuid REFERENCES users(id),user_version bigint,consent_id uuid,consent_version bigint,scopes text[] NOT NULL,revoked_at timestamptz,expires_at timestamptz NOT NULL);
CREATE TABLE oauth_tokens(token_hash text PRIMARY KEY,family_id uuid NOT NULL REFERENCES oauth_token_families(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN('access','refresh')),expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE INDEX oauth_token_expiry ON oauth_tokens(expires_at);
UPDATE instance_state SET schema_version=45 WHERE singleton=1;
